const mail = $json.body || {};
const subject = String(mail.subject || '').slice(0, 500);
const sender = String(mail.sender || '').slice(0, 500);
const body = String(mail.body || '').slice(0, 20000);
const attachments = Array.isArray(mail.attachmentNames) ? mail.attachmentNames.slice(0, 30).map(name => String(name).slice(0, 180)) : [];
if (!subject || !sender) throw new Error('Invalid mail extraction request');
return { json: { ai_input: `Today's date: ${new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kathmandu', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date())}. Time zone: Asia/Kathmandu.\nSender: ${sender}\nSubject: ${subject}\nReceived: ${String(mail.receivedAt || 'unknown').slice(0, 40)}\nAttachments: ${attachments.join(', ') || 'none'}\n\n${body || 'The email has no text body. Do not infer its contents from attachments.'}` } };

